insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('1ch-23-17','1ch','역대상',23,17,'엘리에셀의 아들들은 우두머리 르하뱌라 엘리에셀에게 이 외에는 다른 아들이 없고 르하뱌의 아들들은 심히 많았으며',11001),
('1ch-23-18','1ch','역대상',23,18,'이스할의 아들들은 우두머리 슬로밋이요',11002),
('1ch-23-19','1ch','역대상',23,19,'헤브론의 아들들은 우두머리 여리야와 둘째 아마랴와 셋째 야하시엘과 넷째 여가므암이며',11003),
('1ch-23-20','1ch','역대상',23,20,'웃시엘의 아들들은 우두머리 미가와 그 다음 잇시야더라',11004),
('1ch-23-21','1ch','역대상',23,21,'므라리의 아들들은 마흘리와 무시요 마흘리의 아들들은 엘르아살과 기스라',11005),
('1ch-23-22','1ch','역대상',23,22,'엘르아살이 아들이 없이 죽고 딸만 있더니 그의 형제 기스의 아들이 그에게 장가 들었으며',11006),
('1ch-23-23','1ch','역대상',23,23,'무시의 아들들은 마흘리와 에델과 여레못 세 사람이더라',11007),
('1ch-23-24','1ch','역대상',23,24,'이는 다 레위 자손이니 그 조상의 가문을 따라 계수된 이름이 기록되고 여호와의 성전에서 섬기는 일을 하는 이십세 이상 된 우두머리들이라',11008),
('1ch-23-25','1ch','역대상',23,25,'다윗이 이르기를 이스라엘 하나님 여호와께서 평강을 그의 백성에게 주시고 예루살렘에 영원히 거하시나니',11009),
('1ch-23-26','1ch','역대상',23,26,'레위 사람이 다시는 성막과 그 가운데에서 쓰는 모든 기구를 멜 필요가 없다 한지라',11010),
('1ch-23-27','1ch','역대상',23,27,'다윗의 유언대로 레위 자손이 이십 세 이상으로 계수되었으니',11011),
('1ch-23-28','1ch','역대상',23,28,'그 직분은 아론의 자손을 도와 여호와의 성전과 뜰과 골방에서 섬기고 또 모든 성물을 정결하게 하는 일 곧 하나님의 성전에서 섬기는 일과',11012),
('1ch-23-29','1ch','역대상',23,29,'또 진설병과 고운 가루의 소제물 곧 무교전병이나 과자를 굽는 것이나 반죽하는 것이나 또 모든 저울과 자를 맡고',11013),
('1ch-23-30','1ch','역대상',23,30,'아침과 저녁마다 서서 여호와께 감사하고 찬송하며',11014),
('1ch-23-31','1ch','역대상',23,31,'또 안식일과 초하루와 절기에 모든 번제를 여호와께 드리되 그가 명령하신 규례의 정한 수효대로 항상 여호와 앞에 드리며',11015),
('1ch-23-32','1ch','역대상',23,32,'또 회막의 직무와 성소의 직무와 그들의 형제 아론 자손의 직무를 지켜 여호와의 성전에서 수종드는 것이더라',11016),
('1ch-24-1','1ch','역대상',24,1,'아론 자손의 계열들이 이러하니라 아론의 아들들은 나답과 아비후와 엘르아살과 이다말이라',11017),
('1ch-24-2','1ch','역대상',24,2,'나답과 아비후가 그들의 아버지보다 먼저 죽고 그들에게 아들이 없으므로 엘르아살과 이다말이 제사장의 직분을 행하였더라',11018),
('1ch-24-3','1ch','역대상',24,3,'다윗이 엘르아살의 자손 사독과 이다말의 자손 아히멜렉과 더불어 그들을 나누어 각각 그 섬기는 직무를 맡겼는데',11019),
('1ch-24-4','1ch','역대상',24,4,'엘르아살의 자손 중에 우두머리가 이다말의 자손보다 많으므로 나눈 것이 이러하니 엘르아살 자손의 우두머리가 열여섯 명이요 이다말 자손은 그 조상들의 가문을 따라 여덟 명이라',11020),
('1ch-24-5','1ch','역대상',24,5,'이에 제비 뽑아 피차에 차등이 없이 나누었으니 이는 성전의 일을 다스리는 자와 하나님의 일을 다스리는 자가 엘르아살의 자손 중에도 있고 이다말의 자손 중에도 있음이라',11021),
('1ch-24-6','1ch','역대상',24,6,'레위 사람 느다넬의 아들 서기관 스마야가 왕과 방백과 제사장 사독과 아비아달의 아들 아히멜렉과 및 제사장과 레위 사람의 우두머리 앞에서 그 이름을 기록하여 엘르아살의 자손 중에서 한 집을 뽑고 이다말의 자손 중에서 한 집을 뽑았으니',11022),
('1ch-24-7','1ch','역대상',24,7,'첫째로 제비 뽑힌 자는 여호야립이요 둘째는 여다야요',11023),
('1ch-24-8','1ch','역대상',24,8,'셋째는 하림이요 넷째는 스오림이요',11024),
('1ch-24-9','1ch','역대상',24,9,'다섯째는 말기야요 여섯째는 미야민이요',11025),
('1ch-24-10','1ch','역대상',24,10,'일곱째는 학고스요 여덟째는 아비야요',11026),
('1ch-24-11','1ch','역대상',24,11,'아홉째는 예수아요 열째는 스가냐요',11027),
('1ch-24-12','1ch','역대상',24,12,'열한째는 엘리아십이요 열두째는 야김이요',11028),
('1ch-24-13','1ch','역대상',24,13,'열셋째는 ?바요 열넷째는 예세브압이요',11029),
('1ch-24-14','1ch','역대상',24,14,'열다섯째는 빌가요 열여섯째는 임멜이요',11030),
('1ch-24-15','1ch','역대상',24,15,'열일곱째는 헤실이요 열여덟째는 합비세스요',11031),
('1ch-24-16','1ch','역대상',24,16,'열아홉째는 브다히야요 스무째는 여헤스겔이요',11032),
('1ch-24-17','1ch','역대상',24,17,'스물한째는 야긴이요 스물두째는 가물이요',11033),
('1ch-24-18','1ch','역대상',24,18,'스물셋째는 들라야요 스물넷째는 마아시야라',11034),
('1ch-24-19','1ch','역대상',24,19,'이와 같은 직무에 따라 여호와의 성전에 들어가서 그의 아버지 아론을 도왔으니 이는 이스라엘의 하나님 여호와께서 명하신 규례더라',11035),
('1ch-24-20','1ch','역대상',24,20,'레위 자손 중에 남은 자는 이러하니 아므람의 아들들 중에는 수바엘이요 수바엘의 아들들 중에는 예드야며',11036),
('1ch-24-21','1ch','역대상',24,21,'르하뱌에게 이르러는 그의 아들들 중에 우두머리 잇시야요',11037),
('1ch-24-22','1ch','역대상',24,22,'이스할의 아들들 중에는 슬로못이요 슬로못의 아들들 중에는 야핫이요',11038),
('1ch-24-23','1ch','역대상',24,23,'헤브론의 아들들은 장자 여리야와 둘째 아마랴와 셋째 야하시엘과 넷째 여가므암이요',11039),
('1ch-24-24','1ch','역대상',24,24,'웃시엘의 아들들은 미가요 미가의 아들들 중에는 사밀이요',11040),
('1ch-24-25','1ch','역대상',24,25,'미가의 아우는 잇시야라 잇시야의 아들들 중에는 스가랴이며',11041),
('1ch-24-26','1ch','역대상',24,26,'므라리의 아들들은 마흘리와 무시요 야아시야의 아들들은 브노이니',11042),
('1ch-24-27','1ch','역대상',24,27,'므라리의 자손 야아시야에게서 난 자는 브노와 소함과 삭굴과 이브리요',11043),
('1ch-24-28','1ch','역대상',24,28,'마흘리의 아들 중에는 엘르아살이니 엘르아살은 아들이 없으며',11044),
('1ch-24-29','1ch','역대상',24,29,'기스에게 이르러는 그의 아들 여라므엘이요',11045),
('1ch-24-30','1ch','역대상',24,30,'무시의 아들들은 마흘리와 에델과 여리못이니 이는 다 그 조상의 가문에 따라 기록한 레위 자손이라',11046),
('1ch-24-31','1ch','역대상',24,31,'이 여러 사람도 다윗 왕과 사독과 아히멜렉과 제사장과 레위 우두머리 앞에서 그들의 형제 아론 자손처럼 제비 뽑혔으니 장자의 가문과 막내 동생의 가문이 다름이 없더라',11047),
('1ch-25-1','1ch','역대상',25,1,'다윗이 군대 지휘관들과 더불어 아삽과 헤만과 여두둔의 자손 중에서 구별하여 섬기게 하되 수금과 비파와 제금을 잡아 신령한 노래를 하게 하였으니 그 직무대로 일하는 자의 수효는 이러하니라',11048),
('1ch-25-2','1ch','역대상',25,2,'아삽의 아들들은 삭굴과 요셉과 느다냐와 아사렐라니 이 아삽의 아들들이 아삽의 지휘 아래 왕의 명령을 따라 신령한 노래를 하며',11049),
('1ch-25-3','1ch','역대상',25,3,'여두둔에게 이르러서는 그의 아들들 그달리야와 스리와 여사야와 시므이와 하사뱌와 맛디디야 여섯 사람이니 그의 아버지 여두둔의 지휘 아래 수금을 잡아 신령한 노래를 하며 여호와께 감사하며 찬양하며',11050),
('1ch-25-4','1ch','역대상',25,4,'헤만에게 이르러는 그의 아들들 북기야와 맛다냐와 웃시엘과 스브엘과 여리못과 하나냐와 하나니와 엘리아다와 깃달디와 로맘디에셀과 요스브가사와 말로디와 호딜과 마하시옷이라',11051),
('1ch-25-5','1ch','역대상',25,5,'이는 다 헤만의 아들들이니 나팔을 부는 자들이며 헤만은 하나님의 말씀을 가진 왕의 선견자라 하나님이 헤만에게 열네 아들과 세 딸을 주셨더라',11052),
('1ch-25-6','1ch','역대상',25,6,'이들이 다 그들의 아버지의 지휘 아래 제금과 비파와 수금을 잡아 여호와의 전에서 노래하여 하나님의 전을 섬겼으며 아삽과 여두둔과 헤만은 왕의 지휘 아래 있었으니',11053),
('1ch-25-7','1ch','역대상',25,7,'그들과 모든 형제 곧 여호와 찬송하기를 배워 익숙한 자의 수효가 이백팔십팔 명이라',11054),
('1ch-25-8','1ch','역대상',25,8,'이 무리의 큰 자나 작은 자나 스승이나 제자를 막론하고 다같이 제비 뽑아 직임을 얻었으니',11055),
('1ch-25-9','1ch','역대상',25,9,'첫째로 제비 뽑힌 자는 아삽의 아들 중 요셉이요 둘째는 그달리야이니 그와 그의 형제들과 아들들 십이 명이요',11056),
('1ch-25-10','1ch','역대상',25,10,'셋째는 삭굴이니 그의 아들들과 형제들과 십이 명이요',11057),
('1ch-25-11','1ch','역대상',25,11,'넷째는 이스리이니 그의 아들들과 형제들과 십이 명이요',11058),
('1ch-25-12','1ch','역대상',25,12,'다섯째는 느다냐니 그의 아들들과 형제들과 십이 명이요',11059),
('1ch-25-13','1ch','역대상',25,13,'여섯째는 북기야니 그의 아들들과 형제들과 십이 명이요',11060),
('1ch-25-14','1ch','역대상',25,14,'일곱째는 여사렐라니 그의 아들들과 형제들과 십이 명이요',11061),
('1ch-25-15','1ch','역대상',25,15,'여덟째는 여사야니 그의 아들들과 형제들과 십이 명이요',11062),
('1ch-25-16','1ch','역대상',25,16,'아홉째는 맛다냐니 그의 아들들과 형제들과 십이 명이요',11063),
('1ch-25-17','1ch','역대상',25,17,'열째는 시므이니 그의 아들들과 형제들과 십이 명이요',11064),
('1ch-25-18','1ch','역대상',25,18,'열한째는 아사렐이니 그의 아들들과 형제들과 십이 명이요',11065),
('1ch-25-19','1ch','역대상',25,19,'열두째는 하사뱌니 그의 아들들과 형제들과 십이 명이요',11066),
('1ch-25-20','1ch','역대상',25,20,'열셋째는 수바엘이니 그의 아들들과 형제들과 십이 명이요',11067),
('1ch-25-21','1ch','역대상',25,21,'열넷째는 맛디디야니 그의 아들들과 형제들과 십이 명이요',11068),
('1ch-25-22','1ch','역대상',25,22,'열다섯째는 여레못이니 그의 아들들과 형제들과 십이 명이요',11069),
('1ch-25-23','1ch','역대상',25,23,'열여섯째는 하나냐니 그의 아들들과 형제들과 십이 명이요',11070),
('1ch-25-24','1ch','역대상',25,24,'열일곱째는 요스브가사니 그의 아들들과 형제들과 십이 명이요',11071),
('1ch-25-25','1ch','역대상',25,25,'열여덟째는 하나니니 그의 아들들과 형제들과 십이 명이요',11072),
('1ch-25-26','1ch','역대상',25,26,'열아홉째는 말로디니 그의 아들들과 형제들과 십이 명이요',11073),
('1ch-25-27','1ch','역대상',25,27,'스무째는 엘리아다니 그의 아들들과 형제들과 십이 명이요',11074),
('1ch-25-28','1ch','역대상',25,28,'스물한째는 호딜이니 그의 아들들과 형제들과 십이 명이요',11075),
('1ch-25-29','1ch','역대상',25,29,'스물두째는 깃달디니 그의 아들들과 형제들과 십이 명이요',11076),
('1ch-25-30','1ch','역대상',25,30,'스물셋째는 마하시옷이니 그의 아들들과 형제들과 십이 명이요',11077),
('1ch-25-31','1ch','역대상',25,31,'스물넷째는 로맘디에셀이니 그의 아들들과 형제들과 십이 명이었더라',11078),
('1ch-26-1','1ch','역대상',26,1,'고라 사람들의 문지기 반들은 이러하니라 아삽의 가문 중 고레의 아들 므셀레먀라',11079),
('1ch-26-2','1ch','역대상',26,2,'므셀레먀의 아들들인 맏아들 스가랴와 둘째 여디야엘과 셋째 스바댜와 넷째 야드니엘과',11080),
('1ch-26-3','1ch','역대상',26,3,'다섯째 엘람과 여섯째 여호하난과 일곱째 엘여호에내이며',11081),
